1	package kafka
2	
3	import (
4		"context"
5	
6		eventsv1 "github.com/Sokol111/ecommerce-catalog-service-api/gen/go/catalog/events/v1"
7		apiEvents "github.com/Sokol111/ecommerce-catalog-service-api/pkg/events"
8		"github.com/Sokol111/ecommerce-catalog-service/internal/application/product"
9		"github.com/Sokol111/ecommerce-commons/pkg/kafka/outbox"
10		"github.com/samber/lo"
11		"google.golang.org/protobuf/types/known/timestamppb"
12	)
13	
14	type productEventFactory struct{}
15	
16	// NewProductEventFactory creates a new ProductEventFactory
17	func NewProductEventFactory() product.ProductEventFactory {
18		return &productEventFactory{}
19	}
20	
21	func toProductEventAttributeValue(pAttr product.AttributeValue) *eventsv1.AttributeValue {
22		av := &eventsv1.AttributeValue{
23			AttributeId:   pAttr.AttributeID,
24			AttributeSlug: pAttr.AttributeSlug,
25		}
26		switch {
27		case pAttr.OptionSlugValue != nil:
28			av.Value = &eventsv1.AttributeValue_OptionSlugValue{OptionSlugValue: *pAttr.OptionSlugValue}
29		case len(pAttr.OptionSlugValues) > 0:
30			av.Value = &eventsv1.AttributeValue_OptionSlugValues{OptionSlugValues: &eventsv1.StringList{Values: pAttr.OptionSlugValues}}
31		case pAttr.NumericValue != nil:
32			av.Value = &eventsv1.AttributeValue_NumericValue{NumericValue: *pAttr.NumericValue}
33		case pAttr.TextValue != nil:
34			av.Value = &eventsv1.AttributeValue_TextValue{TextValue: *pAttr.TextValue}
35		case pAttr.BooleanValue != nil:
36			av.Value = &eventsv1.AttributeValue_BooleanValue{BooleanValue: *pAttr.BooleanValue}
37		}
38		return av
39	}
40	
41	func toProductEventAttributes(productAttrs []product.AttributeValue) []*eventsv1.AttributeValue {
42		if len(productAttrs) == 0 {
43			return nil
44		}
45		return lo.Map(productAttrs, func(pAttr product.AttributeValue, _ int) *eventsv1.AttributeValue {
46			return toProductEventAttributeValue(pAttr)
47		})
48	}
49	
50	func (f *productEventFactory) newProductUpdatedEvent(p *product.Product) *eventsv1.ProductUpdatedEvent {
51		return &eventsv1.ProductUpdatedEvent{
52			ProductId:   p.ID,
53			Name:        p.Name,
54			Description: p.Description,
55			Price:       p.Price,
56			Quantity:    int32(p.Quantity),
57			Enabled:     p.Enabled,
58			Version:     int64(p.Version),
59			ImageId:     p.ImageID,
60			CategoryId:  p.CategoryID,
61			CreatedAt:   timestamppb.New(p.CreatedAt),
62			ModifiedAt:  timestamppb.New(p.ModifiedAt),
63			Attributes:  toProductEventAttributes(p.Attributes),
64		}
65	}
66	
67	func (f *productEventFactory) NewProductUpdatedOutboxMessage(ctx context.Context, p *product.Product) outbox.Message {
68		event := f.newProductUpdatedEvent(p)
69		return outbox.Message{
70			Event: event,
71			Key:   p.ID,
72			Topic: apiEvents.TopicFor(event),
73		}
74	}
75	
76	func (f *productEventFactory) NewProductDeletedOutboxMessage(ctx context.Context, productID string) outbox.Message {
77		event := &eventsv1.ProductDeletedEvent{
78			ProductId: productID,
79		}
80		return outbox.Message{
81			Event: event,
82			Key:   productID,
83			Topic: apiEvents.TopicFor(event),
84		}
85	}
