1	package mongo
2	
3	import (
4		"context"
5		"fmt"
6		"strconv"
7	
8		"github.com/samber/lo"
9	
10		"github.com/Sokol111/ecommerce-commons/pkg/core/logger"
11		commonsmongo "github.com/Sokol111/ecommerce-commons/pkg/mongo"
12		"github.com/Sokol111/ecommerce-product-query-service/internal/application/productview"
13		"go.mongodb.org/mongo-driver/v2/bson"
14		mongodriver "go.mongodb.org/mongo-driver/v2/mongo"
15		"go.mongodb.org/mongo-driver/v2/mongo/options"
16		"go.uber.org/zap"
17	)
18	
19	type productViewRepository struct {
20		*commonsmongo.GenericRepository[productview.ProductView, ProductViewEntity]
21		mapper *ProductViewMapper
22	}
23	
24	func NewProductViewRepository(genericRepository *commonsmongo.GenericRepository[productview.ProductView, ProductViewEntity], mapper *ProductViewMapper) (productview.Repository, error) {
25		return &productViewRepository{
26			GenericRepository: genericRepository,
27			mapper:            mapper,
28		}, nil
29	}
30	
31	func (r *productViewRepository) Upsert(ctx context.Context, product *productview.ProductView) error {
32		entity := r.mapper.ToEntity(product)
33	
34		filter := bson.M{
35			"_id":     entity.ID,
36			"version": bson.M{"$lt": entity.Version},
37		}
38	
39		// Replace document, but preserve image URLs if imageId hasn't changed.
40		// This prevents "flickering" when product is updated but image stays the same,
41		// since image-service only publishes ProductImagePromoted on promotion, not on every product update.
42		update := bson.A{
43			bson.M{
44				"$replaceWith": bson.M{
45					"$mergeObjects": bson.A{
46						entity,
47						bson.M{
48							"smallImageUrl": bson.M{
49								"$cond": bson.M{
50									"if":   bson.M{"$eq": bson.A{"$imageId", entity.ImageID}},
51									"then": "$smallImageUrl",
52									"else": nil,
53								},
54							},
55							"largeImageUrl": bson.M{
56								"$cond": bson.M{
57									"if":   bson.M{"$eq": bson.A{"$imageId", entity.ImageID}},
58									"then": "$largeImageUrl",
59									"else": nil,
60								},
61							},
62						},
63					},
64				},
65			},
66		}
67	
68		opts := options.UpdateOne().SetUpsert(true)
69		result, err := r.Collection(ctx).UpdateOne(ctx, filter, update, opts)
70		if err != nil {
71			return fmt.Errorf("failed to upsert product view: %w", err)
72		}
73	
74		if result.MatchedCount == 0 && result.UpsertedCount == 0 {
75			logger.Get(ctx).Debug("version conflict during upsert", zap.String("id", product.ID))
76		}
77	
78		return nil
79	}
80	
81	func (r *productViewRepository) UpdateImageURLs(ctx context.Context, productID, imageID, smallImageURL, largeImageURL string) error {
82		// Only update if the document's imageId matches - prevents overwriting with stale data
83		// when product was already updated with a different image
84		filter := bson.D{
85			{Key: "_id", Value: productID},
86			{Key: "imageId", Value: imageID},
87		}
88		update := bson.D{
89			{Key: "$set", Value: bson.D{
90				{Key: "smallImageUrl", Value: smallImageURL},
91				{Key: "largeImageUrl", Value: largeImageURL},
92			}},
93		}
94	
95		result, err := r.Collection(ctx).UpdateOne(ctx, filter, update)
96		if err != nil {
97			return fmt.Errorf("failed to update image URLs: %w", err)
98		}
99	
100		if result.MatchedCount == 0 {
101			logger.Get(ctx).Debug("skipped image URLs update - imageId mismatch or product not found",
102				zap.String("productId", productID),
103				zap.String("imageId", imageID))
104		}
105	
106		return nil
107	}
108	
109	func (r *productViewRepository) FindRandom(ctx context.Context, count int) ([]*productview.ProductView, error) {
110		pipeline := mongodriver.Pipeline{
111			{{Key: "$match", Value: bson.D{{Key: "enabled", Value: true}}}},
112			{{Key: "$sample", Value: bson.D{{Key: "size", Value: count}}}},
113		}
114	
115		cursor, err := r.Collection(ctx).Aggregate(ctx, pipeline)
116		if err != nil {
117			return nil, fmt.Errorf("failed to aggregate random products: %w", err)
118		}
119		defer func() { _ = cursor.Close(ctx) }() //nolint:errcheck // cursor.Close error is not actionable
120	
121		var entities []ProductViewEntity
122		if err = cursor.All(ctx, &entities); err != nil {
123			return nil, fmt.Errorf("failed to decode products: %w", err)
124		}
125	
126		return lo.Map(entities, func(e ProductViewEntity, _ int) *productview.ProductView {
127			return r.mapper.ToDomain(&e)
128		}), nil
129	}
130	
131	func (r *productViewRepository) FindList(ctx context.Context, query productview.ListQuery) (*commonsmongo.PageResult[productview.ProductView], error) {
132		filter := r.buildListFilter(query)
133	
134		var sortBson bson.D
135		if query.Sort != "" {
136			sortOrder := 1 // asc
137			if query.Order == "desc" {
138				sortOrder = -1
139			}
140			sortBson = bson.D{{Key: query.Sort, Value: sortOrder}}
141		}
142	
143		opts := commonsmongo.QueryOptions{
144			Filter: filter,
145			Page:   query.Page,
146			Size:   query.Size,
147			Sort:   sortBson,
148		}
149	
150		return r.FindWithOptions(ctx, opts)
151	}
152	
153	func (r *productViewRepository) buildListFilter(query productview.ListQuery) bson.D {
154		filter := bson.D{{Key: "enabled", Value: true}}
155	
156		if query.CategoryID != nil {
157			filter = append(filter, bson.E{Key: "categoryId", Value: *query.CategoryID})
158		}
159	
160		filter = r.appendPriceFilter(filter, query.MinPrice, query.MaxPrice)
161		filter = r.appendAttributeFilters(filter, query.AttributeFilters)
162	
163		return filter
164	}
165	
166	func (r *productViewRepository) appendPriceFilter(filter bson.D, minPrice, maxPrice *float64) bson.D {
