164		attrs := lo.FilterMap(p.Attributes, func(attr productview.AttributeValue, i int) (*productqueryv1.AttributeValue, bool) {
165			return mapAttributeValueToProto(attr, i, attrByID)
166		})
167		return &productqueryv1.Product{
168			Id:            p.ID,
169			Name:          p.Name,
170			Description:   p.Description,
171			Price:         p.Price,
172			Quantity:      int32(p.Quantity), //nolint:gosec // Quantity is a product inventory count, practically bounded
173			ImageId:       p.ImageID,
174			SmallImageUrl: p.SmallImageURL,
175			LargeImageUrl: p.LargeImageURL,
176			CategoryId:    p.CategoryID,
177			Attributes:    attrs,
178		}
179	}
