181	func mapAttributeValueToProto(attr productview.AttributeValue, index int, attrByID map[string]*attributeview.AttributeView) (*productqueryv1.AttributeValue, bool) {
182		master, ok := attrByID[attr.AttributeID]
183		if !ok || !master.Enabled {
184			return nil, false
185		}
186	
187		optionsBySlug := lo.KeyBy(master.Options, func(opt attributeview.AttributeOption) string { return opt.Slug })
188	
189		var values []*productqueryv1.AttributeValueItem
190	
191		switch string(master.Type) {
192		case "single":
193			if attr.OptionSlugValue != nil {
194				if opt, ok := optionsBySlug[*attr.OptionSlugValue]; ok {
195					values = []*productqueryv1.AttributeValueItem{{
196						Slug:      attr.OptionSlugValue,
197						Value:     opt.Name,
198						ColorCode: opt.ColorCode,
199					}}
200				}
201			}
202		case "multiple":
203			values = lo.FilterMap(attr.OptionSlugValues, func(slug string, _ int) (*productqueryv1.AttributeValueItem, bool) {
204				opt, ok := optionsBySlug[slug]
205				if !ok {
206					return nil, false
207				}
208				s := slug
209				return &productqueryv1.AttributeValueItem{
210					Slug:      &s,
211					Value:     opt.Name,
212					ColorCode: opt.ColorCode,
213				}, true
214			})
215		case "range":
216			if attr.NumericValue != nil {
217				values = []*productqueryv1.AttributeValueItem{{
218					Value: strconv.FormatFloat(*attr.NumericValue, 'f', -1, 64),
219				}}
220			}
221		case "boolean":
222			if attr.BooleanValue != nil {
223				values = []*productqueryv1.AttributeValueItem{{
224					Value: strconv.FormatBool(*attr.BooleanValue),
225				}}
226			}
227		case "text":
228			if attr.TextValue != nil {
229				values = []*productqueryv1.AttributeValueItem{{Value: *attr.TextValue}}
230			}
231		}
232	
233		return &productqueryv1.AttributeValue{
234			AttributeId: attr.AttributeID,
235			Slug:        attr.Slug,
236			Name:        master.Name,
237			Type:        stringToProtoAttributeType(string(master.Type)),
238			Unit:        master.Unit,
239			Role:        productqueryv1.AttributeRole_ATTRIBUTE_ROLE_SPECIFICATION,
240			SortOrder:   int32(index), //nolint:gosec // index is array position in product attributes, cannot overflow
241			Values:      values,
242		}, true
243	}
244	
245	func protoToAttributeFilters(filters []*productqueryv1.AttributeFilter) []productview.AttributeFilter {
246		return lo.Map(filters, func(f *productqueryv1.AttributeFilter, _ int) productview.AttributeFilter {
247			return productview.AttributeFilter{
248				Slug:   f.GetSlug(),
249				Values: f.GetValues(),
250				Min:    f.Min,
251				Max:    f.Max,
252			}
253		})
254	}
255	
256	func stringToProtoAttributeType(s string) productqueryv1.AttributeType {
257		switch s {
258		case "single":
259			return productqueryv1.AttributeType_ATTRIBUTE_TYPE_SINGLE
260		case "multiple":
261			return productqueryv1.AttributeType_ATTRIBUTE_TYPE_MULTIPLE
262		case "range":
263			return productqueryv1.AttributeType_ATTRIBUTE_TYPE_RANGE
264		case "boolean":
265			return productqueryv1.AttributeType_ATTRIBUTE_TYPE_BOOLEAN
266		case "text":
267			return productqueryv1.AttributeType_ATTRIBUTE_TYPE_TEXT
268		default:
269			return productqueryv1.AttributeType_ATTRIBUTE_TYPE_UNSPECIFIED
270		}
271	}
